-- Robot24 employees from Employees-Updated.xlsx (41 people). Run once in Supabase > SQL Editor, after updates 17 to 23.
-- Safe to run again: anyone already on the Staff list (same name) is skipped.
-- Working days are set to Monday to Friday for everyone; change anyone who works Monday to Saturday on their profile.


select status, count(*) as people, sum(monthly_salary) as monthly_salaries_aed from public.staff group by status order by status;
